def transform(grid):
    out = [row[:] for row in grid]
    marked_rows = {r for r, row in enumerate(grid) if 0 in row}
    marked_cols = {c for c in range(len(grid[0])) if any(grid[r][c] == 0 for r in range(len(grid)))}
    # Erase the marked rows and columns, preserving color 2.
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if (r in marked_rows or c in marked_cols) and grid[r][c] != 2:
                out[r][c] = 0
    return out
